const tok = lines.join(' ').split(/\s+/).filter(s => s.length).map(Number);
const n = tok[0], k = tok[1];
const pre = new Array(n + 1).fill(0);
for (let i = 0; i < n; i++) pre[i + 1] = pre[i] + tok[2 + i];
const INF = 4e18;
let prev = new Array(n + 1).fill(INF);
prev[0] = 0;
for (let j = 1; j <= k; j++) {
  const cur = new Array(n + 1).fill(INF);
  const compute = (lo, hi, optlo, opthi) => {
    if (lo > hi) return;
    const mid = (lo + hi) >> 1;
    let best = INF, bp = -1;
    for (let p = optlo; p <= Math.min(mid - 1, opthi); p++) {
      if (prev[p] < INF) {
        const v = prev[p] + (pre[mid] - pre[p]) * (pre[mid] - pre[p]);
        if (v < best) { best = v; bp = p; }
      }
    }
    cur[mid] = best;
    compute(lo, mid - 1, optlo, bp);
    compute(mid + 1, hi, bp, opthi);
  };
  compute(j, n, j - 1, n - 1);
  prev = cur;
}
