import java.io.*;
import java.util.*;

public class Main {
    static long[] pre, prev, cur;
    static final long INF = Long.MAX_VALUE / 4;

    static void compute(int lo, int hi, int optlo, int opthi) {
        if (lo > hi) return;
        int mid = (lo + hi) / 2;
        long best = INF;
        int bp = -1;
        for (int p = optlo; p <= Math.min(mid - 1, opthi); p++) {
            if (prev[p] < INF) {
                long d = pre[mid] - pre[p];
                long v = prev[p] + d * d;
                if (v < best) { best = v; bp = p; }
            }
        }
        cur[mid] = best;
        compute(lo, mid - 1, optlo, bp);
        compute(mid + 1, hi, bp, opthi);
    }

    public static void main(String[] args) throws IOException {
        StreamTokenizer in = new StreamTokenizer(new BufferedInputStream(System.in));
        in.nextToken();
        int n = (int) in.nval;
        in.nextToken();
        int k = (int) in.nval;
        pre = new long[n + 1];
        for (int i = 0; i < n; i++) { in.nextToken(); pre[i + 1] = pre[i] + (long) in.nval; }
        prev = new long[n + 1];
        Arrays.fill(prev, INF);
        prev[0] = 0;
        for (int j = 1; j <= k; j++) {
            cur = new long[n + 1];
            Arrays.fill(cur, INF);
            compute(j, n, j - 1, n - 1);
            prev = cur;
        }
        System.out.println(prev[n]);
    }
}

