#include <bits/stdc++.h>
using namespace std;

const long long INF = LLONG_MAX / 4;
vector<long long> pre, prev_, cur_;

void compute(int lo, int hi, int optlo, int opthi) {
    if (lo > hi) return;
    int mid = (lo + hi) / 2;
    long long best = INF;
    int bp = -1;
    for (int p = optlo; p <= min(mid - 1, opthi); p++) {
        if (prev_[p] < INF) {
            long long d = pre[mid] - pre[p];
            long long v = prev_[p] + d * d;
            if (v < best) { best = v; bp = p; }
        }
    }
    cur_[mid] = best;
    compute(lo, mid - 1, optlo, bp);
    compute(mid + 1, hi, bp, opthi);
}

int main() {
    int n, k;
    scanf("%d %d", &n, &k);
    pre.assign(n + 1, 0);
    for (int i = 0; i < n; i++) { long long x; scanf("%lld", &x); pre[i + 1] = pre[i] + x; }
    prev_.assign(n + 1, INF);
    prev_[0] = 0;
    for (int j = 1; j <= k; j++) {
        cur_.assign(n + 1, INF);
        compute(j, n, j - 1, n - 1);
        prev_ = cur_;
    }
    printf("%lld\n", prev_[n]);
    return 0;
}
